def clamp(value, lo, hi):
    """Return value restricted to the closed range [lo, hi]."""
    return max(lo, min(value, hi))

def is_palindrome(s):
    filtered = ''.join(c for c in s.lower() if c.isalnum())
    return filtered == filtered[::-1]

def average(nums):
    if not nums:
        return None
    return sum(nums) / len(nums)

def safe_divide(a, b):
    if b == 0:
        raise ValueError('division by zero')
    return a / b

def flatten(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

import string

def most_common_word(text):
    # Convert to lowercase and remove punctuation
    text = text.lower()
    translator = str.maketrans('', '', string.punctuation)
    cleaned_text = text.translate(translator)
    words = cleaned_text.split()

    if not words:
        return None

    # Count frequencies and track first occurrence
    word_count = {}
    first_index = {}

    for i, word in enumerate(words):
        if word not in first_index:
            first_index[word] = i
        word_count[word] = word_count.get(word, 0) + 1

    # Find most common word, breaking ties by first occurrence
    max_count = max(word_count.values())
    return min(
        (word for word, count in word_count.items() if count == max_count),
        key=lambda w: first_index[w]
    )

