def parse_int_or_raise(s):
    if s is None:
        raise ValueError("Cannot parse None as integer")

    try:
        s_stripped = s.strip()
    except AttributeError:
        raise ValueError("Cannot parse non-string input as integer")

    if not s_stripped:
        raise ValueError("Cannot parse empty string as integer")

    try:
        return int(s_stripped)
    except ValueError:
        raise
    except Exception:
        raise ValueError("Cannot parse input as integer")

