def has_pair_with_sum(nums, target):
    seen = set()
    for num in nums:
        complement = target - num
        if complement in seen:
            return True
        seen.add(num)
    return False

def pluralize(word, count):
    if count == 1:
        return word

    # Words ending in consonant + 'y': change 'y' to 'ies'
    if len(word) >= 2 and word[-1] == 'y':
        vowels = 'aeiou'
        if word[-2] not in vowels:
            return word[:-1] + 'ies'

    # Words ending in 's', 'x', 'ch', or 'sh': append 'es'
    if word.endswith(('s', 'x')):
        return word + 'es'
    if word.endswith(('ch', 'sh')):
        return word + 'es'

    # Everything else: append 's'
    return word + 's'

def dedupe_preserve_order(items):
    seen = set()
    result = []
    for item in items:
        normalized = item.strip().lower()
        if normalized not in seen:
            seen.add(normalized)
            result.append(item)
    return result
